<div class='page-header mb-3'><div class='row align-items-center'><div class='col'><h2 class='page-title'>الفترات المحاسبية</h2></div><div class='col-auto'><form class='d-flex gap-2' method='post' action='/accounting/periods'><input type='hidden' name='_token' value='<?=e($csrfToken)?>'><input class='form-control' type='number' name='fiscal_year' min='2000' max='2200' value='<?=date('Y')?>'><button class='btn btn-primary'>إنشاء 12 فترة</button></form></div></div></div><div class='card'><table class='table'><thead><tr><th>السنة</th><th>الفترة</th><th>من</th><th>إلى</th><th>الحالة</th><th></th></tr></thead><tbody><?php foreach($periods as$p):?><tr><td><?=e($p['fiscal_year'])?></td><td><?=e($p['period_no'])?></td><td><?=e($p['start_date'])?></td><td><?=e($p['end_date'])?></td><td><?=$p['status']==='open'?'مفتوحة':'مغلقة'?></td><td><form method='post' action='/accounting/periods/<?=e($p['id'])?>/status'><input type='hidden' name='_token' value='<?=e($csrfToken)?>'><input type='hidden' name='status' value='<?=$p['status']==='open'?'closed':'open'?>'><button class='btn btn-sm btn-outline-primary'><?=$p['status']==='open'?'إغلاق':'فتح'?></button></form></td></tr><?php endforeach;?></tbody></table></div>
